DEPLOY.LEGACY.CONSTRAINT_NOT_ENFORCED.bad:
// MySQL records the constraint and then does not apply it. Nothing fails, nothing
// warns, and every write that violates the rule succeeds.
DB::statement('ALTER TABLE invoices ADD CONSTRAINT invoices_total_positive CHECK (total >= 0) NOT ENFORCED');

DEPLOY.LEGACY.CONSTRAINT_NOT_ENFORCED.good:
// ENFORCED is the default, so saying nothing would say this too. It is written out
// because the difference between the two lines is the entire finding.
DB::statement('ALTER TABLE invoices ADD CONSTRAINT invoices_total_positive CHECK (total >= 0) ENFORCED');

DEPLOY.LEGACY.CONSTRAINT_NOT_VALIDATED.bad:
// The constraint is added without scanning the rows already in the table, which is the
// right move on a live one. Nothing here finishes the job, so the table enforces the
// rule for new rows and claims nothing about the old ones — indefinitely.
DB::statement('ALTER TABLE orders ADD CONSTRAINT orders_total_positive CHECK (total >= 0) NOT VALID');

DEPLOY.LEGACY.CONSTRAINT_NOT_VALIDATED.good:
// Two statements, and the second is the one that finishes it. NOT VALID takes a brief
// lock instead of scanning; VALIDATE CONSTRAINT then does the scan without blocking
// reads or writes.
DB::statement('ALTER TABLE orders ADD CONSTRAINT orders_total_positive CHECK (total >= 0) NOT VALID');
DB::statement('ALTER TABLE orders VALIDATE CONSTRAINT orders_total_positive');

GEN.L1.DOWN_MORE_DESTRUCTIVE.bad:
// up() adds a column:
Schema::table('orders', fn (Blueprint $table) => $table->string('status')->nullable());
// down(), in the same migration, drops the whole table:
Schema::dropIfExists('orders');

GEN.L3.DML_ON_SCHEMA_CHANGED_TABLE.good:
