Schema::table('orders', fn (Blueprint $table) => $table->string('status')->nullable());
// Migration 2 (or a queued job), after the first has committed — backfill in batches:
// DB::table('orders')->whereNull('status')->limit(1000)->update(['status' => 'new']);

GEN.L4.DOWN_MISSING.bad:
// The down() body, as this migration leaves it. Laravel rolls back by calling down()
// and nothing else, so `migrate:rollback` reports success and changes nothing. A down()
// that is absent entirely is the same outcome with one fewer clue.
// (nothing here)

MY.L1.DROP_COLUMN.good:
// Stop writing and reading the column in a shipped release first, then drop it
// later behind #[SqlensAllowDestructive]. On MySQL the drop is DDL, so it commits
// itself the moment it runs - there is no transaction to take it back.

MY.L1.TRUNCATE.good:
// Bounded batches: reversible while it runs, and no implicit commit throws away
// the transaction you thought you were in.
DB::statement('DELETE FROM sessions WHERE last_activity < UNIX_TIMESTAMP(NOW() - INTERVAL 30 DAY) LIMIT 1000');

MY.L2.COPY_ALTER_CHARSET.good:
// Convert one column at a time, so each deploy re-encodes less data and can be scheduled
// on its own — and let MySQL refuse rather than lock the table if it cannot stay online:
DB::statement('ALTER TABLE orders MODIFY note TEXT CHARACTER SET utf8mb4, LOCK=NONE');

MY.L2.COPY_ALTER_TYPE.good:
// Add the widened column, backfill it in batches, then cut over in a later migration —
// the table stays writable the whole time:
Schema::table('orders', fn (Blueprint $table) => $table->unsignedBigInteger('total_cents_new')->nullable());

MY.L3.ALGORITHM_LOCK_UNEXPRESSIBLE.good:
// Raw SQL on purpose: Laravel's MySQL grammar cannot emit ALGORITHM/LOCK, and naming them
// makes the server refuse rather than silently copy the table if it cannot do this in place.
DB::statement('ALTER TABLE orders ADD PRIMARY KEY (id), ALGORITHM=INPLACE, LOCK=NONE');

MY.L3.MISSING_LOCK_WAIT_TIMEOUT.bad:
// No bound: if the table is busy, this waits for the metadata lock
// until it gets one — the default is a year.
Schema::table('orders', function (Blueprint $table) {
    $table->text('note')->nullable();
});

MY.L3.MISSING_LOCK_WAIT_TIMEOUT.good:
// Bound the wait first. MySQL has no SET LOCAL, so this is SET SESSION
// and stays for the rest of the connection.
DB::statement('SET SESSION lock_wait_timeout = 3');

Schema::table('orders', function (Blueprint $table) {
    $table->text('note')->nullable();
});

MY.L3.MIXED_DDL_DML_NOT_ATOMIC.good:
// Migration 1 — schema only. It either completes or leaves nothing behind:
Schema::table('orders', fn (Blueprint $table) => $table->string('status')->nullable());
// Migration 2 (or a queued job), after the first has run — data only:
// DB::table('orders')->whereNull('status')->limit(1000)->update(['status' => 'new']);

MY.L4.ENUM_CHANGE.good:
// Append at the end, which is the one enum change MySQL applies instantly and the one
// no deployed code can be surprised by — every existing value keeps its meaning:
Schema::table('orders', fn (Blueprint $table) => $table->enum('status', ['draft', 'sent', 'paid', 'refunded'])->change());

MY.L4.EXPAND_WITHOUT_CONTRACT.bad:
// Migration 1 — expand, and back-fill from the column being replaced:
DB::statement('ALTER TABLE orders ADD COLUMN total_cents bigint');
DB::statement('UPDATE orders SET total_cents = total * 100');
// …and no migration ever drops `total`. The table now carries both, and the older one
// stops being written the moment the last deploy moves over — silently.

MY.L4.EXPAND_WITHOUT_CONTRACT.good:
// Migration 1 — expand and back-fill, unchanged. This half was always right:
DB::statement('ALTER TABLE orders ADD COLUMN total_cents bigint');
DB::statement('UPDATE orders SET total_cents = total * 100');

// Migration 2, AFTER every deployed reader uses the new column — contract:
DB::statement('ALTER TABLE orders DROP COLUMN total');

MY.L7.UNBATCHED_MASS_DML.good:
// MySQL accepts LIMIT on UPDATE, so a chunk is readable in the statement itself:
DB::table('orders')->where('status', 'old')->limit(1000)->update(['status' => 'new']);
// …or walk a key range, which bounds it just as well:
// DB::table('orders')->whereBetween('id', [$from, $to])->update(['status' => 'new']);

