SEC.AUTH.ROLE_ANONYMOUS.bad:
-- An empty user name. Not unused — it matches ANY name the server
-- does not otherwise know, from a host matching its pattern.
CREATE USER ''@'localhost' IDENTIFIED BY 'a real secret';

SEC.AUTH.ROLE_ANONYMOUS.good:
-- Give the account a name, so it can only be used by something that knows it.
CREATE USER 'reporting'@'localhost' IDENTIFIED BY 'a real secret';

-- …or remove the anonymous one, which is what a current server ships without.
DROP USER ''@'localhost';

SEC.AUTH.ROLE_DEPRECATED_PASSWORD_HASH_L.bad:
-- Locked, and still carrying the old verifier it will come back with
ALTER USER 'legacy'@'%' IDENTIFIED WITH mysql_native_password BY 'secret';
ALTER USER 'legacy'@'%' ACCOUNT LOCK;

SEC.AUTH.ROLE_DEPRECATED_PASSWORD_HASH_L.good:
-- Give it a current verifier while it is out of use…
ALTER USER 'legacy'@'%' IDENTIFIED WITH caching_sha2_password BY 'secret';

-- …or drop it, if nothing needs it.
DROP USER 'legacy'@'%';

SEC.AUTH.ROLE_NO_PASSWORD.bad:
-- MySQL: a password plugin with nothing stored under it.
-- The server accepts this and treats an empty credential as a valid login.
CREATE USER 'reporting'@'%' IDENTIFIED WITH caching_sha2_password;

SEC.AUTH.ROLE_NO_PASSWORD.good:
-- Either give it a password…
ALTER USER 'reporting'@'%' IDENTIFIED BY 'a real secret';

-- …or say out loud that the credential lives elsewhere, which is a
-- different arrangement and not an empty password.
ALTER USER 'reporting'@'localhost' IDENTIFIED WITH auth_socket;

SEC.AUTH.ROLE_NO_PASSWORD_LOCKED.bad:
-- Locked, and with nothing behind the lock.
CREATE USER 'legacy_import'@'%' IDENTIFIED WITH caching_sha2_password;
ALTER USER 'legacy_import'@'%' ACCOUNT LOCK;

SEC.AUTH.ROLE_NO_PASSWORD_LOCKED.good:
-- Give it a password while it is out of use…
ALTER USER 'legacy_import'@'%' IDENTIFIED BY 'a real secret';

-- …or drop it, if nothing needs it any more.
DROP USER 'legacy_import'@'%';

SEC.AUTH.ROLE_WILDCARD_HOST_PRIVILEGED.bad:
-- Reachable from anywhere, and able to do anything once it arrives.
CREATE USER 'deploy'@'%' IDENTIFIED BY 'a real secret';
GRANT ALL PRIVILEGES ON *.* TO 'deploy'@'%' WITH GRANT OPTION;

SEC.AUTH.ROLE_WILDCARD_HOST_PRIVILEGED.good:
-- Narrow the host, and grant only what the account actually uses.
CREATE USER 'deploy'@'10.0.0.%' IDENTIFIED BY 'a real secret';
GRANT SELECT, INSERT, UPDATE, DELETE ON app.* TO 'deploy'@'10.0.0.%';

SEC.CFG.LOCAL_INFILE_FILE_GRANT.good:
# Close the capability, and take FILE off any account that does not need it.
local_infile = OFF

#   REVOKE FILE ON *.* FROM 'reporting'@'%';

