return [
    'connections' => [
        'pgsql' => ['driver' => 'pgsql', 'username' => env('DB_USERNAME')],
        'pgsql_migrations' => ['driver' => 'pgsql', 'username' => env('DB_MIGRATION_USERNAME')],
