SEC.PRIV.GRANT_ALL.bad:
-- Everything the engine has, on everything the server holds.
GRANT ALL PRIVILEGES ON *.* TO 'app'@'10.0.0.%';

-- The same state, one database wide. Still every privilege MySQL has there.
GRANT ALL PRIVILEGES ON shop.* TO 'app'@'10.0.0.%';

SEC.PRIV.GRANT_ALL.good:
-- What the application actually does at run time, and nothing else.
GRANT SELECT, INSERT, UPDATE, DELETE ON shop.* TO 'app'@'10.0.0.%';

-- Schema changes belong to the account that deploys them.
GRANT ALL PRIVILEGES ON shop.* TO 'deploy'@'10.0.0.%';

SEC.PRIV.GRANT_OPTION.good:
-- The same access, without the ability to widen the server.
GRANT SELECT, INSERT ON shop.* TO 'app'@'10.0.0.%';

-- On an account that already has it, this takes back only the handing-on:
REVOKE GRANT OPTION FOR SELECT, INSERT ON shop.* FROM 'app'@'10.0.0.%';

SEC.PRIV.GRANT_OPTION_STRUCTURAL.good:
-- Structural rights stay with the account that deploys migrations…
GRANT CREATE ON shop.* TO 'deploy'@'10.0.0.%';

-- …and the application account keeps only what it uses at run time.
GRANT SELECT, INSERT, UPDATE, DELETE ON shop.* TO 'app'@'10.0.0.%';

SEC.PRIV.GRANT_PROCESS.good:
-- The application account does not need to watch other sessions.
REVOKE PROCESS ON *.* FROM 'app'@'10.0.0.%';

-- A monitoring account is a different account, and keeps it:
GRANT PROCESS, REPLICATION CLIENT ON *.* TO 'monitoring'@'10.0.0.9';

SEC.PRIV.GRANT_PUBLIC.bad:
-- Every role in the database can now read this table, including roles nobody has created yet.
GRANT SELECT ON invoices TO PUBLIC;

-- And this one lets every role create objects in the schema.
GRANT USAGE, CREATE ON SCHEMA reporting TO PUBLIC;

SEC.PRIV.GRANT_PUBLIC.good:
-- Name the role that needs it. A grant you can review is a grant you can revoke.
GRANT SELECT ON invoices TO reporting_reader;

GRANT USAGE ON SCHEMA reporting TO reporting_reader;

SEC.PRIV.GRANT_SERVER_ADMIN.bad:
-- Neither of these needs SUPER, and both make the account a server administrator.
GRANT SYSTEM_VARIABLES_ADMIN ON *.* TO 'app'@'10.0.0.%';
GRANT SET_ANY_DEFINER ON *.* TO 'app'@'10.0.0.%';

SEC.PRIV.GRANT_SERVER_ADMIN.good:
-- Whatever the application actually uses, and nothing that reaches the server itself.
GRANT SELECT, INSERT, UPDATE, DELETE ON shop.* TO 'app'@'10.0.0.%';

-- On an account that already holds one:
REVOKE SYSTEM_VARIABLES_ADMIN, SET_ANY_DEFINER ON *.* FROM 'app'@'10.0.0.%';

SEC.PRIV.ROLE_BYPASSRLS.good:
ALTER ROLE reporting NOBYPASSRLS;

-- If a job legitimately reads across tenants, give it a policy that says so out loud.
CREATE POLICY reporting_all ON invoices FOR SELECT TO reporting USING (true);

SEC.PRIV.ROLE_SUPERUSER.bad:
-- The obvious form.
ALTER ROLE app SUPERUSER;

-- And the one that hides: `app` looks ordinary in every listing.
GRANT postgres TO app;

SEC.PRIV.ROLE_SUPERUSER.good:
REVOKE postgres FROM app;

-- Give the application what it needs, by name.
GRANT USAGE ON SCHEMA public TO app;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO app;

SEC.PRIV.ROUTINE_DEFINER.good:
CREATE FUNCTION app.grant_access(uid bigint) RETURNS void
    LANGUAGE sql
    SECURITY DEFINER
    SET search_path = pg_catalog
AS $$
    INSERT INTO public.memberships (user_id, granted_at) VALUES (uid, pg_catalog.now());
$$;

-- and the grant that goes with it: one role, one routine, nothing wider
GRANT EXECUTE ON FUNCTION app.grant_access(bigint) TO app_runtime;

SEC.PRIV.ROUTINE_DEFINER_MUTABLE_PATH.bad:
CREATE FUNCTION app.grant_access(uid bigint) RETURNS void
    LANGUAGE sql
    SECURITY DEFINER
AS $$
    INSERT INTO memberships (user_id, granted_at) VALUES (uid, now());
$$;

SEC.PRIV.ROUTINE_DEFINER_UNSAFE_PATH.bad:
-- public is writable by anyone here, which was PostgreSQL's own default before 15
GRANT CREATE ON SCHEMA public TO PUBLIC;

CREATE FUNCTION app.grant_access(uid bigint) RETURNS void
    LANGUAGE sql
    SECURITY DEFINER
    -- pinned, and still open: someone else can define now() in public
    SET search_path = public
AS $$
    INSERT INTO memberships (user_id, granted_at) VALUES (uid, now());
$$;

SEC.PRIV.RUNTIME_DDL.good:
-- The runtime role, and nothing more than it needs.
GRANT USAGE ON SCHEMA app TO app_runtime;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA app TO app_runtime;

-- The DDL stays with the role that deploys.
REVOKE CREATE ON SCHEMA app FROM app_runtime;

